import{_ as e,o as r,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"サービスの状態","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/service-status.md","filePath":"ja-JP/user-guide/settings/service-status.md","lastUpdated":1785993908000}'),o={name:"ja-JP/user-guide/settings/service-status.md"};function n(i,t,l,g,p,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="サービスの状態" tabindex="-1">サービスの状態 <a class="header-anchor" href="#サービスの状態" aria-label="Permalink to &quot;サービスの状態&quot;">​</a></h1><p>バックグラウンドインデックスサービスを管理し、そのログをリアルタイムで確認できます。</p><h2 id="サービス制御" tabindex="-1">サービス制御 <a class="header-anchor" href="#サービス制御" aria-label="Permalink to &quot;サービス制御&quot;">​</a></h2><p>ステータスカードには、昇格されたインデクサーの現在の状態 — <strong>インストール中</strong>、<strong>インデックス中</strong>、<strong>準備完了</strong>(ファイル/フォルダー数をリアルタイム表示)、<strong>エラー</strong> — が対応するアイコン(スピナー、チェックマーク、エラーバッジ)とともに表示されます。</p><p><strong>サービスをインストールして開始</strong> ボタンは、サービスがまだインストールされていないか、エラーが発生した場合にのみ表示されます。インストールされて実行中になると、このページには手動での開始/停止/アンインストールのコントロールはありません — サービスはバックグラウンドで動作し続けることが前提です。</p><h2 id="ログ" tabindex="-1">ログ <a class="header-anchor" href="#ログ" aria-label="Permalink to &quot;ログ&quot;">​</a></h2><p>Lertaro が実行する3つのプロセス(昇格されたバックグラウンドインデクサー、操作対象であるユーザー単位の App、キーボードフック処理を行うプロセス)に対応する3つのタブ — <strong>App</strong>、<strong>Hook</strong>、<strong>Service</strong> — があります。各タブには、そのプロセスのログ行がレベルごとに色分けされて表示されます。</p><ul><li><strong>レベルフィルター</strong> ドロップダウン — すべて / エラー / 警告 / 情報 / デバッグ。</li><li><strong>検索ボックス</strong> — レベルフィルターと組み合わせて、表示中の行をキーワードで絞り込みます。</li><li><strong>クリア</strong> ボタン — 現在選択中のタブのログを消去します。Service タブのログのクリアはサービス自身を経由します(App プロセスには直接書き込む権限がないため)。App と Hook のログはユーザー単位のファイルであるため、直接クリアされます。</li></ul><p>トラブルシューティングの際は、まずここを確認してください。<a href="./../troubleshooting.html#それでも解決しない場合">トラブルシューティング</a>も参照してください。</p>',9)])])}const _=e(o,[["render",n]]);export{u as __pageData,_ as default};
